// Format environment parameters as YAML for GitOps
const data = items[0].json;
const envName = data.name || 'test-env';
const filePath = `gitops/environments/${envName}/values.yaml`;

const lines = [
  `name: ${data.name}`,
  `blueprint: ${data.blueprint}`,
  `owner: "${data.owner}"`,
  `team: ${data.team}`,
  `size: ${data.size}`,
  `image: ${data.image}`,
  `expiresAt: "${data.expiresAt}"`,
  `requestId: "${data.requestId}"`
];
if (data.port) lines.push(`port: ${data.port}`);
if (data.ingress !== undefined) lines.push(`ingress: ${data.ingress}`);
if (data.schedule) lines.push(`schedule: "${data.schedule}"`);
if (data.command) lines.push(`command: [${data.command.map(c => JSON.stringify(c)).join(', ')}]`);

return [{
  json: {
    branch: `env/${envName}-${data.requestId}`,
    baseBranch: 'main',
    filePath,
    fileContent: lines.join('\n') + '\n',
    title: `feat(env): provision ephemeral environment ${envName}`,
    body: `### DevAIPortal Automated Provisioning\n\n- **Environment**: \`${envName}\`\n- **Blueprint**: \`${data.blueprint}\`\n- **Owner**: \`${data.owner}\`\n- **Expires At**: \`${data.expiresAt}\`\n- **Request ID**: \`${data.requestId}\``,
    ...data
  }
}];
